def reverse_string(
    input_string,
):
    reversed_chars = []
    for char_index in range(
        len(input_string) - 1,
        -1,
        -1,
    ):
        reversed_chars.append(
            input_string[
                char_index
            ],
        )
    return "".join(
        reversed_chars,
    )

def test_reverse_string():
    assert reverse_string(
        "hello",
    ) == "olleh"
    assert reverse_string(
        "Python",
    ) == "nohtyP"
    assert reverse_string(
        "",
    ) == ""
    assert reverse_string(
        "a",
    ) == "a"
    assert reverse_string(
        "racecar",
    ) == "racecar"

if __name__ == "__main__":
    test_reverse_string()
    print(
        reverse_string(
            "example",
        ),
    )

