def calculate_factorial(n):
    if n < 0:
        raise ValueError(
            "Factorial is not defined for negative numbers.",
        )
    if n == 0:
        return 1

    result = 1
    for i in range(
        1,
        n + 1,
    ):
        result *= i

    return result

def main():
    print(
        "Factorial of 5:",
        calculate_factorial(5),
    )
    print(
        "Factorial of 0:",
        calculate_factorial(0),
    )
    print(
        "Factorial of 10:",
        calculate_factorial(10),
    )
    print(
        "Factorial of 3:",
        calculate_factorial(3),
    )
    print(
        "Factorial of 1:",
        calculate_factorial(1),
    )

if __name__ == "__main__":
    main()

