def caesar_cipher_encrypt(
    text,
    shift,
):
    result = []
    for char in text:
        if 'a' <= char <= 'z':
            shifted_char = chr(
                (
                    ord(char)
                    - ord('a')
                    + shift
                )
                % 26
                + ord('a')
            )
            result.append(
                shifted_char,
            )
        elif 'A' <= char <= 'Z':
            shifted_char = chr(
                (
                    ord(char)
                    - ord('A')
                    + shift
                )
                % 26
                + ord('A')
            )
            result.append(
                shifted_char,
            )
        else:
            result.append(
                char,
            )
    return "".join(
        result,
    )

