    processed_data = []
    start_index = 1 if header_included else 0
    for i in range(
            start_index,
            len(csv_lines),
    ):
        line = csv_lines[i]
        parsed_fields = parse_csv_line(
            line,
        )

        current_row = []
        for field in parsed_fields:
            if strip_whitespace:
                field = field.strip(
                )
            if remove_empty and not field:
                continue
            current_row.append(
                field,
            )

        if max_fields is not None:
            current_row = current_row[:max_fields]

