def seconds_to_hms(
    seconds,
):
    hours = seconds // 3600
    minutes = (
        seconds
        % 3600
    ) // 60
    remaining_seconds = (
        seconds
        % 60
    )

    return "{:02d}:{:02d}:{:02d}".format(
        hours,
        minutes,
        remaining_seconds,
    )

def main():
    print(
        seconds_to_hms(
            3661,
        )
    )
    print(
