def is_valid_parentheses(s: str) -> bool:
    stack = []
    mapping = {
        ")": "(",
        "}": "{",
        "]": "[",
    }

    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if top_element != mapping[char]:
                return False
        else:
            stack.append(char)

    return not stack

def _test_cases():
    assert is_valid_parentheses(
        "()[]{}"
    ) == True
    assert is_valid_parentheses(
        "([{}])"
    ) == True
    assert is_valid_parentheses(
        "([)]"
    ) == False
    assert is_valid_parentheses(
        "{[]}"
    ) == True
    assert is_valid_parentheses(
        ""
    ) == True
    assert is_valid_parentheses(
        "("
    ) == False
    assert is_valid_parentheses(
        "((("
    ) == False
    assert is_valid_parentheses(
        ")))"
    ) == False
    assert is_valid_parentheses(
        "({[()]})"
    ) == True
    assert is_valid_parentheses(
        "((()))"
    ) == True
    assert is_valid_parentheses(
        "({[("
    ) == False

_test_cases()

