def nth_fibonacci(
    n,
):
    """
    Calculates the Nth Fibonacci number.

    Args:
        n (int): The index of the Fibonacci number to calculate.

    Returns:
        int: The Nth Fibonacci number.
    """
    if n <= 1:
        return n
    else:
        a = 0
        b = 1
        for _ in range(
            2,
            n + 1,
        ):
            a, b = (
                b,
                a + b,
            )
        return b


def _test_fibonacci(
    test_cases,
):
    for (
        input_n,
        expected_output,
    ) in test_cases:
