def decrypt_caesar(
    text,
    shift,
):
    decrypted_text = []
    for char in text:
        if 'a' <= char <= 'z':
            decrypted_char_code = (
                ord(char)
                - ord('a')
                - shift
            ) % 26 + ord('a')
            decrypted_text.append(
                chr(decrypted_char_code)
            )
        else:
            decrypted_text.append(
                char
            )
    return "".join(
        decrypted_text
    )

