def weighted_average(
    values,
    weights,
):
    """
    Calculates the weighted average of a list of values and their corresponding weights.
    """
    if not values or not weights:
        raise ValueError(
            "Input lists cannot be empty."
        )

    if len(values) != len(weights):
        raise ValueError(
            "Values and weights lists must have the same length."
        )

    sum_products = sum(
        value * weight
        for value, weight in zip(
            values,
            weights,
        )
    )
    sum_weights = sum(
        weights
    )

    if sum_weights == 0:
        raise ValueError(
            "Sum of weights cannot be zero."
        )

    return (
        sum_products
        / sum_weights
    )

