from collections import Counter

def least_frequent_char(
    text: str,
) -> str:
    if not text:
        return ""

    char_counts = Counter(text)

    min_count = float('inf')
    least_char = ''

    for char in text:
        current_count = char_counts[char]
        if current_count < min_count:
