from collections import Counter

def least_frequent_char(text: str) -> str:
    if not text:
        return ""

    char_counts = Counter(text)

    min_count = float('inf')
    least_char = ''

    for char in text:
        current_count = char_counts[char]
        if current_count < min_count:
            min_count = current_count
            least_char = char
        elif (current_count == min_count and text.index(char) < text.index(least_char)):
            least_char = char

    return least_char

def main():
