def flatten_dict(
    nested_dict,
    separator,
):
    flattened_dict = {}
    for (
        key,
        value,
    ) in nested_dict.items():
        if isinstance(
            value,
            dict,
        ):
            for (
                sub_key,
                sub_value,
            ) in value.items():
                flattened_dict[
                    f"{key}{separator}{sub_key}"
                ] = sub_value
        else:
            flattened_dict[
                key
            ] = value
    return flattened_dict

