from collections import defaultdict

def group_anagrams(
    words: list[str],
) -> list[list[str]]:
    anagram_map = defaultdict(list)
    for word in words:
        sorted_word = "".join(
            sorted(
                word,
            )
        )
        anagram_map[sorted_word].append(
            word,
        )
    return list(
        anagram_map.values(),
    )

