def _split_string(
    input_string: str,
    delimiter: str,
    strip_whitespace: bool,
    max_splits: int,
) -> list[str]:
    """Helper function to split a string."""
    parts = input_string.split(
        sep=delimiter,
        maxsplit=max_splits,
    )
    if strip_whitespace:
        return [
            part.strip(
                chars=" \t\n\r\f\v",
            )
            for part in parts
        ]
    return parts

