def is_valid_luhn(
    card_number: str,
) -> bool:
    total_sum = 0
    num_digits = len(card_number)

    for i, digit_char in enumerate(
        card_number,
    ):
        digit = int(
            digit_char,
        )
        if (num_digits - 1 - i) % 2 == 1:
            doubled_digit = digit * 2
            total_sum += (
                doubled_digit - 9
                if doubled_digit > 9
                else doubled_digit
            )
        else:
            total_sum += digit

    return (
