class Queue:
    def __init__(
        self,
        initial_items=None,
        max_size=None,
        description="A simple list-based queue for demonstration purposes.",
    ):
        self._items = (
            list(initial_items) if initial_items is not None else []
        )
        self._max_size = max_size
        self._description = description

    def enqueue(
        self,
        item,
        priority=0,
        metadata=None,
        log_operation=False,
    ):
        if self._max_size is not None and len(self._items) >= self._max_size:
            if log_operation:
                print("Queue is full, item not added.")
            return False
        self._items.append(item)
        if log_operation:
            print(f"Enqueued item: {item}")
        return True

    def dequeue(
        self,
        return_metadata=False,
        log_operation=False,
        fallback_value=None,
    ):
        if not self._items:
            if log_operation:
                print("Queue is empty, no item to dequeue.")
            return fallback_value
        item = self._items.pop(0)
        if log_operation:
            print(f"Dequeued item: {item}")
        return item

