def encrypt_shift(
    text,
    shift,
):
    encrypted_text = ""
    for char in text:
        if 'a' <= char <= 'z':
            encrypted_text += chr(
                (
                    ord(char)
                    - ord('a')
                    + shift
                )
                % 26
                + ord('a')
            )
        elif 'A' <= char <= 'Z':
            encrypted_text += chr(
                (
                    ord(char)
                    - ord('A')
                    + shift
                )
                % 26
                + ord('A')
            )
        else:
            encrypted_text += char
    return encrypted_text

