    exponent,
):
    """
    Calculates the result of a base number raised to an exponent.
    """
    if exponent == 0:
        return 1
    elif exponent > 0:
        result = 1
        for _ in range(
            exponent,
        ):
            result *= base
        return result
    else:
        positive_exponent_result = calculate_power(
            base,
            -exponent,
        )
        return 1 / positive_exponent_result

if __name__ == '__main__':
    power1 = calculate_power(
        2,
        3,
    )
    print(
        f"2 raised to the power of 3 is: {power1}"
    )

    power2 = calculate_power(
        5,
        0,
    )
    print(
        f"5 raised to the power of 0 is: {power2}"
    )

    power3 = calculate_power(
        10.0,
        -2,
    )
    print(
        f"10.0 raised to the power of -2 is: {power3}"
    )

    power4 = calculate_power(
        -3,
