import math


def geometric_mean(
    numbers,
):
    if not numbers:
        return 0.0

    product = 1.0
    for num in numbers:
        if num <= 0:
            return 0.0
        product *= num

    return product ** (
        1
        / len(
            numbers,
        )
    )


def calculate_and_display_mean(
    data_list,
    label,
):
    mean_value = geometric_mean(
        data_list,
    )
    print(
        f"Geometric mean of {label}: {mean_value}",
    )


