def convert_base(
    number,
    base,
):
    if not (2 <= base <= 16):
        raise ValueError(
            "Base must be between 2 and 16, inclusive.",
        )

    if number == 0:
        return "0"

    digits = (
        "0123456789ABCDEF"
    )
    result = []

    while number > 0:
        remainder = (
            number % base
        )
        result.append(
            digits[remainder]
        )
        number //= base

    return "".join(
        reversed(result)
    )

