def xor_cipher(
    text,
    key_char,
):
    """
    Encrypts/decrypts text using a XOR cipher with a single character key.
    """
    result = []
    key_val = ord(key_char)
    for char_val in map(
        ord,
        text,
    ):
        result.append(
            chr(
                char_val
                ^ key_val,
            )
        )
    return "".join(
        result,
    )

def _test_xor_cipher():
    assert xor_cipher(
        "Hello",
        "A",
    ) == '\x09\x04\x0f\x0f\x0a'
    assert xor_cipher(
        xor_cipher(
            "Test",
            "B",
        ),
        "B",
    ) == "Test"
    assert xor_cipher(
        "Python",
        "K",
    ) == '\x15\x00\x1a\x11\x0e\x1b'
    assert xor_cipher(
        xor_cipher(
            "Another example string",
            "X",
        ),
        "X",
    ) == "Another example string"
    assert xor_cipher(
        "",
        "Z",
    ) == ""

if __name__ == '__main__':
    _test_xor_cipher()

def is_palindrome_string(s):
    cleaned_string = "".join(
        char
        for char in s
        if char.isalnum()
    ).lower()

    return cleaned_string == cleaned_string[::-1]

def example_usage():
    print(
        is_palindrome_string(
            'Racecar'
        )
    )
