def common_keys(
    dict1,
    dict2,
):
    set1 = set(
        dict1.keys(),
    )
    set2 = set(
        dict2.keys(),
    )
    return set1.intersection(
        set2,
    )

def main():
    example1 = common_keys(
        {'a': 1, 'b': 2},
        {'b': 3, 'c': 4},
    )
    print(f"Example 1: {example1}")

    example2 = common_keys(
        {'x': 1},
        {'y': 2},
    )
    print(f"Example 2: {example2}")

    example3 = common_keys(
        {'apple': 10, 'banana': 20, 'cherry': 30},
        {'banana': 5, 'date': 15, 'cherry': 25},
    )
    print(f"Example 3: {example3}")

if __name__ == '__main__':
    main()

