def generate_permutations(
    lst,
):
    if not lst:
        return [[]]

    if len(lst) == 1:
        return [lst]

    all_permutations = []
    for i, item in enumerate(
        lst,
    ):
        remaining_elements = (
            lst[:i] + lst[i + 1 :]
        )
        for perm in generate_permutations(
            remaining_elements,
        ):
            all_permutations.append(
                [item] + perm,
            )

    return all_permutations

def example_usage():
    print(
        generate_permutations(
            [1, 2],
        ),
    )
    print(
        generate_permutations(
            ['a'],
        ),
    )
    print(
        generate_permutations(
            ['x', 'y', 'z'],
        ),
    )
    print(
        generate_permutations(
            [],
        ),
    )
    print(
        generate_permutations(
            [1, 2, 3, 4],
        ),
    )

if __name__ == "__main__":
    example_usage()

