def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if (n % i == 0):
            return False
    return True

def example_usage():
    print("Is 7 prime?", is_prime(7))
    print("Is 10 prime?", is_prime(10))
    print("Is 1 prime?", is_prime(1))
    print("Is 2 prime?", is_prime(2))
    print("Is 13 prime?", is_prime(13))

